{
  // Bon fiscal: each minute the receipt is printed line by line from the top, held, and wiped
  const MS = 100, PT = 32, PH = 388, PX = 14, LH = 36;
  const V = {"cover":{"__blank":0,"s":1},"head":{"__blank":0,"s":1}};
  const ease = (t) => { t = Math.max(0, Math.min(1, t)); return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; };
  const tick = () => {
    const now = Date.now(), d = new Date(now), sec = d.getSeconds() + (now % 1000) / 1000;
    let cy = PT - 6, ch = PH + 6;
    if (sec < 0.6) { /* paper still blank */ }
    else if (sec < 6.0) { const r = Math.round(ease((sec - 0.6) / 5.4) * PH / LH) * LH; cy = PT - 6 + r; ch = PH + 6 - r; }
    else if (sec < 58.6) { ch = 0; }
    else { const k = ease((sec - 58.6) / 1.0); ch = Math.round((PH + 6) * k); }
    if (ch > 1) slot('cover')(PX - 8, cy, V.cover.s, 286, ch); else slot('cover').hide();
    if (sec >= 0.6 && sec < 6.0 && ch > 1) slot('head')(PX, cy - 3, V.head.s); else slot('head').hide();
  };
    // ---- shared runtime: slot setter that skips unchanged calls, and a loop that runs only while the face is on screen ----
  const SL = {};
  const slot = (h) => {
    if (SL[h]) return SL[h];
    const w = W[h], f = F[h]; let key = '';
    const s = (x, y, i, ww, hh) => {
      const k = x + '|' + y + '|' + i + '|' + ww + '|' + hh;
      if (k === key) return;
      key = k;
      const p = { x: pxv(x), y: pxv(y) };
      if (i !== undefined) p.src = f[i];
      if (ww !== undefined) { p.w = pxv(ww); p.h = pxv(hh); }
      w.setProperty(ui.prop.MORE, p);
    };
    s.hide = () => { if (key === 'hide') return; key = 'hide'; w.setProperty(ui.prop.MORE, { src: f[V[h].__blank] }); };
    return (SL[h] = s);
  };
  let gen = 0, running = false;
  const safe = () => { try { tick(); } catch (e) { /* a bad frame must not stop the loop */ } };
  const loop = (g) => {
    if (!running || g !== gen) return;
    safe();
    if (running && g === gen) { try { setTimeout(() => loop(g), MS); } catch (e) {} }
  };
  const start = () => {
    gen++; running = true; const g = gen;
    try { setTimeout(() => loop(g), MS); } catch (e) {}
    safe();
  };
  const stop = () => { running = false; gen++; };
  ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: start, pause_call: stop });
  start();

}
